int dp[101][101][101][3];

int dfs(int tv, int tk, int ts, int last, int cv, int ck, int cs) {
    if (tv == cv && tk == ck && ts == cs) {
        return 0;
    }
    if (dp[tv][tk][ts][last] != -1) return dp[tv][tk][ts][last];
    int ret = INT_MAX;
    if (tv < cv) {
        int p = pos[0][tv];
        int move = std::max(freq[p][0] - tv, 0) + std::max(freq[p][1] - tk, 0) + std::max(freq[p][2] - ts, 0) - 1;
        ret = std::min(ret, dfs(tv + 1, tk, ts, 0, cv, ck, cs) + move);
    }
    if (tk < ck && last != 0) {
        int p = pos[1][tk];
        int move = std::max(freq[p][0] - tv, 0) + std::max(freq[p][1] - tk, 0) + std::max(freq[p][2] - ts, 0) - 1;
        ret = std::min(ret, dfs(tv, tk + 1, ts, 1, cv, ck, cs) + move);
