    if (ts < cs) {
        int p = pos[2][ts];
        int move = std::max(freq[p][0] - tv, 0) + std::max(freq[p][1] - tk, 0) + std::max(freq[p][2] - ts, 0) - 1;
        ret = std::min(ret, dfs(tv, tk, ts + 1, 2, cv, ck, cs) + move);
    }
    return dp[tv][tk][ts][last] = ret;
}

